    private TextView label(String t){TextView v=tv(t,10,true,0xFF9299A5);v.setLetterSpacing(.12f);return v;}
    private Button primaryButton(String t){Button b=new Button(this);b.setText(t);b.setAllCaps(false);b.setTextSize(14);b.setTextColor(Color.WHITE);b.setTypeface(Typeface.DEFAULT,Typeface.BOLD);b.setBackground(roundRect(BLUE,18));return b;}
    private Button secondaryButton(String t){Button b=new Button(this);b.setText(t);b.setAllCaps(false);b.setTextSize(13);b.setTextColor(INK);b.setBackground(roundRect(0xFFF0F2F6,16));return b;}
